Mesh<Point, double> result;
for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    RT::Cell_handle c = fit->first;
    unsigned k = fit->second;
    if (!is_large_facet(rt, *fit, threshold)) continue;
    std::array<Point, 3> dual_points;
    for (int i = 0, j = 0; i < 4; ++i) {
        if (i == k) continue;
        RT::Vertex_handle v = c->vertex(i);
        Point p = v->point().point();
        double w = v->point().weight();
        dual_points[j++] = Point(p.x() - w, p.y() - w, p.z() - w);
    }
    Point centroid(0, 0, 0);
    for (int i = 0; i < 3; ++i) {
        centroid = Point(centroid.x() + dual_points[i].x(), centroid.y() + dual_points[i].y(), centroid.z() + dual_points[i].z());
    }
    centroid = Point(centroid.x() / 3.0, centroid.y() / 3.0, centroid.z() / 3.0);
    double area = 0.0;
    for (int i = 0; i < 3; ++i) {
        int j = (i + 1) % 3;
        Point edge1 = Point(dual_points[i].x() - centroid.x(), dual_points[i].y() - centroid.y(), dual_points[i].z() - centroid.z());
        Point edge2 = Point(dual_points[j].x() - centroid.x(), dual_points[j].y() - centroid.y(), dual_points[j].z() - centroid.z());
        Point cross = Point(
            edge1.y() * edge2.z() - edge1.z() * edge2.y(),
            edge1.z() * edge2.x() - edge1.x() * edge2.z(),
            edge1.x() * edge2.y() - edge1.y() * edge2.x()
        );
        area += std::sqrt(cross.x() * cross.x() + cross.y() * cross.y() + cross.z() * cross.z());
    }
    area *= 0.5;
    for (int i = 0; i < 3; ++i) {
        int j = (i + 1) % 3;
        result.add_edge(dual_points[i], dual_points[j], area);
    }
}
return result;

